R=[
(9772614,"कटहल और आलू वाला वीगन चिकन सूप","कटहल, आलू, ब्राउन राइस और ढेर सारी सब्जियां मिलकर वीगन चिकन सूप का एक भरपूर कटोरा तैयार करती हैं!","8 सर्विंग","1 सर्विंग",
["1 लाल प्याज, बारीक कटा हुआ","2 बड़ी गाजर, छिली और टुकड़ों में कटी हुई","2 डंठल सेलरी, टुकड़ों में कटी हुई","200 ग्राम क्रेमिनी मशरूम, कटे हुए, लगभग 6-8 मशरूम","2 शिमला मिर्च, टुकड़ों में कटी हुई, किसी भी रंग की","2 पाउंड पीले आलू, छिले और टुकड़ों में कटे हुए (लगभग 4-5 कप कटे हुए आलू)","20 औंस का 1 डिब्बा कच्चा हरा कटहल, नमकीन पानी या सादे पानी में, चाशनी में नहीं","1 कप ब्राउन राइस","10 कप कम सोडियम वाला सब्जियों का शोरबा","3 तेज पत्ते","¼ छोटा चम्मच सूखा थाइम","¼ छोटा चम्मच सूखा रोज़मेरी","¼ छोटा चम्मच सूखी तुलसी","¼ छोटा चम्मच सूखी सेज","¼ छोटा चम्मच सूखा ओरेगैनो","स्वादानुसार नमक और काली मिर्च","454 ग्राम का 1 पैकेट मध्यम सख्त टोफू, हो सके तो GMO-मुक्त चुनें"],
["एक बड़े पतीले में कटा हुआ प्याज, गाजर, सेलरी, शिमला मिर्च और मशरूम डालें और 1-2 बड़े चम्मच पानी डालें। मध्यम आंच पर नरम होने तक, लगभग 5-8 मिनट भूनें।",
"टोफू को छोड़कर बाकी सारी सामग्री अपने पतीले में डालें और उबाल आने दें। उबाल आने के बाद आंच धीमी कर दें और चावल पकने तक, लगभग 30 मिनट पकाएं। पक जाने पर तेज पत्ते निकाल दें।",
"इसी बीच, टोफू को अपने ब्लेंडर में पीस लें, और ज़रूरत हो तो उसे चलाने के लिए एक-दो बूंद पानी डालें। सूप पक जाने पर आंच बंद कर दें और टोफू को मिलने तक चलाते हुए डालें।",
"चखें और ज़रूरत हो तो नमक और काली मिर्च डालें।"],
["अगर आप चाहें, तो आलू की जगह शकरकंद इस्तेमाल कर सकते हैं। ध्यान रहे कि इससे सूप का स्वाद ज़्यादा मीठा हो जाएगा। मुझे मध्यम सख्त टोफू पसंद है, क्योंकि वह सूप को अच्छी तरह गाढ़ा करता है। लेकिन जो आपके पास हो वही इस्तेमाल करें। मुलायम या सिल्की टोफू भी चलता है। सोया-मुक्त बनाने के लिए, टोफू की जगह एक डिब्बा पिसी हुई सफेद राजमा या कैनेलिनी बीन्स डालें। या फिर, अपनी पसंद का पौधों से बना दूध लगभग 1 कप इस्तेमाल करें। ध्यान रहे कि दूध वाले विकल्प से शोरबा गाढ़ा नहीं होगा, लेकिन उसमें अतिरिक्त मलाईदारपन आएगा। अगर आप प्रोटीन की मात्रा बढ़ाना चाहते हैं, तो टोफू या बीन्स की सलाह दी जाती है। अगर आप नखरेबाज़ खाने वालों को खिला रहे हैं, तो बारीक कटी सब्जियों के लिए फूड प्रोसेसर इस्तेमाल करें। अगर आपको स्ट्यू जैसी बनावट पसंद है, तो सब्जियां हाथ से थोड़ी बड़ी काटें। अगर आपको टोफू पसंद नहीं है, तो चिंता न करें! मैं वादा करती हूं कि आपको सूप में उसका स्वाद नहीं आएगा। टोफू स्वाद बदले बिना सूप में प्यारी मलाईदारी और रेशमीपन जोड़ता है। (लेकिन अगर सेहत के कारणों से आप सोया नहीं खा सकते, तो बदलाव के सुझावों के लिए ऊपर देखें।) आप सारी सब्जियां एक दिन पहले काटकर पहले से तैयारी कर सकते हैं। बस आलू छीलने और काटने के बाद उन्हें पानी में रखें ताकि वे भूरे न पड़ें। बचा हुआ सूप फ्रिज में 3-4 दिन तक रखा जा सकता है, या एयरटाइट डिब्बे में 2 महीने तक फ्रीज़ किया जा सकता है।"],
[]),
(9774483,"वीगन रास्ता पास्ता","हमारे लज़ीज़ वीगन रास्ता पास्ता के साथ कैरिबियन के चटकीले स्वादों का मज़ा लें।","5 सर्विंग","1 सर्विंग",
["½ पाउंड पेने पास्ता या अपनी पसंद के आकार का पास्ता","¼ कप सब्जियों का शोरबा","1 पीला प्याज, बारीक कटा हुआ","3 शिमला मिर्च, किसी भी रंग की","4 लहसुन की कलियां, बारीक कटी हुई","2 बड़े चम्मच जर्क सीज़निंग","2 छोटे चम्मच स्मोक्ड पैपरिका","1 कप सब्जियों का शोरबा","1 कप टमाटर की सॉस","1.5 कप छोले, पके हुए या डिब्बाबंद (लगभग 1-15 औंस का डिब्बा)","1 कप Thai Kitchen नारियल का दूध","वैकल्पिक सजावट::वीगन पार्मेसन चीज़","वैकल्पिक सजावट::काली मिर्च या लाल मिर्च के फ्लेक्स"],
["एक बड़े पतीले में पानी उबालें और अपने पास्ता को पैकेट पर लिखे निर्देशों के अनुसार 'अल डेंते' पास्ता के लिए पकाएं। पक जाने पर छान लें और एक तरफ रख दें।",
"इसी बीच, एक बड़े पैन में 1/4 कप शोरबा, प्याज और कटी हुई शिमला मिर्च डालें और हल्का नरम होने तक, लगभग 5-7 मिनट भूनें। फिर लहसुन डालें और बार-बार चलाते हुए 30-60 सेकंड और भूनें, जब तक खुशबू न आने लगे।",
"बचा हुआ 1 कप शोरबा, टमाटर की सॉस, छोले और नारियल का दूध अपने पैन में डालें और मध्यम आंच पर 5-10 मिनट धीमी आंच पर पकाएं, और आंच बंद कर दें।",
"फिर पके हुए पेने को अपनी सॉस में डालें और पास्ता पर बराबर लगाने के लिए अच्छी तरह मिलाएं। कुछ मिनट रखा रहने दें ताकि पास्ता थोड़ी सॉस सोख ले, और फिर परोसें।"],
["बाज़ार में मिलने वाले जर्क मसालों के मिश्रण में आमतौर पर बहुत चीनी होती है। ब्राउन शुगर की मात्रा पर काबू रखने के लिए अपना मिश्रण खुद बनाएं, या चाहें तो उसे पूरी तरह छोड़ दें।","अपनी सर्विंग छोटी रखें, क्योंकि पास्ता और नारियल का दूध थोड़े भारी होते हैं।","कम वसा के लिए, फुल फैट की जगह लाइट नारियल का दूध इस्तेमाल करें। या आप कोई और डेयरी-मुक्त दूध भी इस्तेमाल कर सकते हैं, लेकिन ध्यान रहे कि सॉस उतनी गाढ़ी नहीं होगी।","अपने पास्ता के पानी में नमक डालें। सबसे अच्छी बनावट और स्वाद के लिए अपने पानी के पतीले में पर्याप्त नमक डालना न भूलें। हर बार पानी में बिल्कुल सही नमक डालने में मदद के लिए यहां एक काम की गाइड है।","अपने पास्ता को अल डेंते पकाएं। ज़्यादा न पकाएं! अल डेंते का मतलब है कि पकने के बाद भी पास्ता कुछ सख्त रहता है, जिससे हर कौर में सबसे बढ़िया बनावट मिलती है। यह ज़्यादा न पके, इसके लिए पैकेट पर बताए गए समय से कुछ मिनट पहले चखना शुरू कर दें। यह नरम होना चाहिए, लेकिन फिर भी थोड़ा सख्त।","बचा हुआ पास्ता फ्रिज में 3-4 दिन तक रखा जा सकता है।"],
[]),
(9775065,"वीगन कुट्टू के वैफल","हमारे वीगन कुट्टू के वैफल का मज़ा लें, जो कुरकुरे, फूले-फूले और बिना किसी अपराधबोध के हैं!","8 वैफल","1 सर्विंग",
["1.25 कप सोया दूध","1 बड़ा चम्मच एप्पल साइडर सिरका या नींबू का रस","180 ग्राम कुट्टू का आटा, लगभग 1.5 कप, चम्मच से भरा और बराबर किया हुआ","1 छोटा चम्मच दालचीनी","1 छोटा चम्मच बेकिंग पाउडर"],
["अपने वैफल आयरन को मध्यम आंच पर, या निर्माता के निर्देशों के अनुसार पहले से गरम करें।",
"एक बड़े बाउल में सोया दूध और एप्पल साइडर सिरका मिलाएं और कुछ मिनट के लिए एक तरफ रख दें। दूध गाढ़ा होकर फट जाएगा, जिससे वीगन छाछ बन जाएगी।",
"दूध फट जाने के बाद, बाकी सारी सामग्री उसी बाउल में डालें और मिलने तक चलाएं। फिर निर्माता के निर्देशों के अनुसार वैफल पकाएं, लगभग 3-5 मिनट, या जब तक मनचाहा पकाव न आ जाए।",
"अपनी पसंदीदा टॉपिंग के साथ परोसें और आनंद लें।"],
["सबसे अच्छे नतीजों के लिए अपने आटे और पाउडर को तौलकर लें। अगर बोरी से सीधे भरकर लेंगे, तो हो सकता है आटा ज़्यादा हो जाए और घोल को सही गाढ़ापन देने के लिए ज़्यादा तरल की ज़रूरत पड़े।","अगर आपके पास किचन स्केल नहीं है, तो आटे को चम्मच से नापने वाले कप में भरें और चाकू से ऊपर का फालतू आटा हटा दें।","वैफल का घोल डालने से पहले यह पक्का कर लें कि आपका वैफल मेकर गरम हो, ताकि वह चिपके नहीं।","ढक्कन बहुत जल्दी न उठाएं वरना आपके वैफल टूट जाएंगे, और चिपकने की जांच के लिए ढक्कन धीरे-धीरे और सावधानी से उठाएं।","बाद के वैफल पहले वाले से थोड़ी जल्दी पकते हैं, इसलिए ध्यान से देखते रहें।"],
[]),
(9779919,"इंस्टेंट पॉट में काली बीन्स [बिना भिगोए]","बिना भिगोए, हर बार इंस्टेंट पॉट में बिल्कुल सही काली बीन्स!","12 सर्विंग","1 सर्विंग",
["1 पाउंड सूखी काली बीन्स, छंटी और धुली हुई","6 कप ताज़ा पानी, या ज़्यादा स्वाद के लिए शोरबा इस्तेमाल करें"],
["अपनी सूखी काली बीन्स को छांटें और कोई भी छोटे कंकड़ या कचरा हटा दें। फिर उन्हें अच्छी तरह धोएं और अपने इंस्टेंट पॉट में रखें। पॉट में 6 कप पानी (या ज़्यादा स्वाद के लिए शोरबा) डालें और ढक्कन बंद करें, यह पक्का करते हुए कि वाल्व सीलिंग की स्थिति में है।",
"हाई पर 30-35 मिनट प्रेशर कुक करें (नोट्स देखें)। प्रेशर बनने और उलटी गिनती शुरू होने में लगभग 15 मिनट लगेंगे। टाइमर पूरा होने पर, 10 मिनट (इससे ज़्यादा नहीं) प्राकृतिक रूप से प्रेशर निकलने दें और फिर बची हुई भाप को तुरंत निकाल दें।",
"ढक्कन खोलें और बीन्स ज़्यादा न पक जाएं, इसके लिए तुरंत छान लें। तुरंत खाएं या आगे के व्यंजनों के लिए रख लें।"],
["सबसे अच्छे नतीजों के लिए ताज़ी बीन्स इस्तेमाल करें, जो महीनों से आपकी पैंट्री में न पड़ी हों। जब बीन्स पुरानी हो जाती हैं, तो वे पकने में बहुत ज़्यादा समय लेती हैं और ज़्यादा नरम नहीं होतीं। मुझे अपनी बीन्स नरम पसंद हैं लेकिन लिजलिजी नहीं, खासकर सलाद या रैप में इस्तेमाल के लिए, इसलिए मुझे लगता है कि 30 मिनट का प्रेशर समय सबसे बढ़िया इंस्टेंट पॉट काली बीन्स देता है। अगर सूप के लिए इस्तेमाल कर रहे हैं और आपको बीन्स ज़्यादा नरम पसंद हैं, तो प्रेशर का समय बढ़ाकर 35 मिनट कर दें। भंडारण: स्टोर करने से पहले अपनी बीन्स को थोड़ा ठंडा होने दें, लेकिन उन्हें 2 घंटे से ज़्यादा कमरे के तापमान पर न छोड़ें, वरना बैक्टीरिया पनपने लग सकते हैं। सुझाव: जल्दी ठंडा होने के लिए उन्हें उथले कटोरों में रखें, और फिर फ्रिज में रखें या फ्रीज़ करें। ज़िप-टॉप बैग या सीलबंद डिब्बों में 3-4 दिन फ्रिज में रखें। फ्रीज़ करने के लिए, अपनी बीन्स को साफ़ तौलिये से थपथपाकर सुखा लें। फिर लगभग 1.5 कप पकी हुई बीन्स नापें और ज़िप-टॉप बैग या फ्रीज़र में रखने लायक एयरटाइट डिब्बों में रखें। यह लगभग 15 औंस के डिब्बे जितनी बीन्स के बराबर है, जो आगे के भोजन के लिए सुविधाजनक मात्रा है। फ्रीज़ करने से पहले अपने ज़िप-टॉप बैग से अतिरिक्त हवा बाहर निकालना न भूलें, ताकि वे ज़्यादा समय तक टिकें, और बैग फटने की संभावना कम हो। 3 महीने तक फ्रीज़ में रखें।"],
[]),
(9784924,"वीगन ऑरेंज चिकन [ग्लूटेन-मुक्त + बिना तेल का]","ताज़ा, स्वादिष्ट और बनाने में आसान वीगन ऑरेंज चिकन, जो आपके स्वाद की कलियों को झूमने पर मजबूर कर देगा!","4 सर्विंग","1 सर्विंग",
["4 औंस सोया कर्ल्स, लगभग Butler’s सोया कर्ल्स के आधे पैक के बराबर","8 औंस मशरूम, कटे हुए","1 लाल शिमला मिर्च, कटी हुई","मैरिनेड के लिए::1 कप कम सोडियम वाला सब्जियों का शोरबा","मैरिनेड के लिए::½ कप संतरे का रस, ताज़ा निचोड़ा हुआ (लगभग 1 बड़ा संतरा)","मैरिनेड के लिए::1 छोटा चम्मच संतरे का छिलका (ज़ेस्ट)","मैरिनेड के लिए::⅓ कप चावल का सिरका","मैरिनेड के लिए::¼ कप तमारी या सोया सॉस, अगर ग्लूटेन से परहेज़ नहीं है","मैरिनेड के लिए::¼ कप मेपल सिरप","मैरिनेड के लिए::1 छोटा चम्मच लहसुन पाउडर","मैरिनेड के लिए::½ छोटा चम्मच पिसी हुई अदरक","मैरिनेड के लिए::1 बड़ा चम्मच कॉर्नस्टार्च या 2 बड़े चम्मच मैदा","परोसने के लिए::वर्मिसेली नूडल्स, ब्राउन राइस या क्विनोआ","परोसने के लिए::तिल","परोसने के लिए::हरी प्याज"],
["एक मध्यम बाउल में कॉर्नस्टार्च या मैदे को छोड़कर मैरिनेड की सारी सामग्री मिलाएं और अच्छी तरह फेंटें। फिर सोया कर्ल्स को बाउल में डालकर चलाएं और उन्हें 10-15 मिनट भीगने दें। यह पक्का करें कि वे सब मैरिनेड में डूब जाएं।",
"इसी बीच, कटे हुए मशरूम और शिमला मिर्च एक बड़ी कड़ाही में डालें। उन्हें नरम करने और कम करने के लिए बिना तेल के 4-5 मिनट भूनें। आपको तेल या पानी की ज़रूरत नहीं होनी चाहिए क्योंकि मशरूम अपना पानी खुद छोड़ेंगे। अगर कुछ चिपक रहा हो, तो थोड़ा सा पानी डालें।",
"छेदों वाले चम्मच या चिमटे से भीगे हुए सोया कर्ल्स को सब्जियों वाली अपनी कड़ाही में डालें और सॉस को बचाकर रखें। कर्ल्स को बाउल से निकालना न भूलें, उन्हें उंडेलें नहीं। सोया कर्ल्स के किनारे भूरे करने के लिए 5 मिनट भूनें।",
"इसी बीच, सॉस के बाउल में कॉर्नस्टार्च डालें और मिलाने के लिए चलाएं। फिर सॉस को कर्ल्स और सब्जियों वाले पैन में डालें। सॉस को गाढ़ा करने के लिए मध्यम आंच पर 3-5 मिनट पकाएं, और परोसें।"],
["ज़्यादा सॉस वाली स्टर फ्राई के लिए मैरिनेड की रेसिपी दोगुनी कर लें।","मैरिनेड के लिए कम सोडियम वाला सब्जियों का शोरबा ही इस्तेमाल करें, क्योंकि तमारी/सोया सॉस में बहुत नमक होता है। अगर आपके पास कम सोडियम वाला शोरबा नहीं है, तो आधा कप शोरबा और आधा कप पानी इस्तेमाल करें।","कम सोडियम के लिए, कम सोडियम वाली तमारी या कम सोडियम वाली सोया सॉस इस्तेमाल करें।","सोया कर्ल्स और सोया चंक्स एक जैसे नहीं होते। ज़्यादातर प्राकृतिक खाद्य पदार्थों की गली या हेल्थ फूड स्टोर में सोया कर्ल्स मिल जाएंगे। या आप उन्हें Amazon पर खरीद सकते हैं।","पोषण संबंधी जानकारी वीगन ऑरेंज चिकन रेसिपी के एक-चौथाई हिस्से के लिए है और इसमें नूडल्स या चावल शामिल नहीं हैं।"],
[]),
(9784963,"बादाम आटे के बनाना ब्रेड मफिन","नम, हल्के मीठे, बेहद स्वादिष्ट केले और बादाम आटे के मफिन!","9 मफिन","1 सर्विंग",
["1 ¼ कप मसला हुआ केला, लगभग 3 बड़े पके केलों से","⅓ कप बिना चीनी वाली सेब की प्यूरी (एपलसॉस)","2 बड़े चम्मच मेपल सिरप","250 ग्राम छिलका उतारे हुए बादाम का आटा, लगभग 2.5 कप से थोड़ा कम","1.5 छोटा चम्मच बेकिंग पाउडर","½ छोटा चम्मच बेकिंग सोडा","1 छोटा चम्मच दालचीनी","वैकल्पिक::½ कप कटे हुए अखरोट या पीकन"],
["ओवन को 350℉/176℃ पर पहले से गरम करें।",
"एक बड़े मिक्सिंग बाउल में केलों को मसलें और एपलसॉस और मेपल सिरप डालें। अच्छी तरह मिलाएं। फिर आटा, बेकिंग पाउडर, बेकिंग सोडा, दालचीनी डालें और मिलने तक चलाएं। फिर अगर कटे हुए अखरोट इस्तेमाल कर रहे हैं, तो उन्हें धीरे से मिला दें।",
"अपने मिश्रण को 9 मफिन टिन में बांटकर भर दें। (नॉनस्टिक, मफिन लाइनर इस्तेमाल करें, या ज़रूरत हो तो चिकनाई लगाएं।) 24-26 मिनट तक बेक करें, जब तक बीच में डाली गई टूथपिक साफ़ न निकले।",
"ज़रूरी: मफिन को वायर रैक पर ले जाने से पहले उन्हें पैन में 10-15 मिनट रखा रहने दें। ओवन से निकलते ही मफिन नरम और नाज़ुक होंगे, लेकिन ठंडे होने पर वे कड़े हो जाएंगे।"],
["बहुत पके केले इस्तेमाल करें! इस रेसिपी में सिर्फ 2 बड़े चम्मच मेपल सिरप है, इसलिए कुदरती मिठास के लिए ऐसे बहुत ज़्यादा पके केले लें जिनके छिलकों पर भूरे धब्बे हों।","अपना आटा तौलकर लें। बोरी से आटा भरकर लेना वज़न के मुकाबले कम सटीक होता है। इसलिए अगर आपके पास किचन स्केल है, तो सबसे अच्छी बनावट और नतीजों के लिए उसका इस्तेमाल करें।","ताज़ा बेकिंग पाउडर इस्तेमाल करें। जो बेकिंग पाउडर 6+ महीने से ज़्यादा समय से खुला है, उसका असर और फुलाने की ताकत कम होने लग सकती है।","हर ओवन अलग होता है, इसलिए तब तक बेक करें जब तक बीच में डाली गई टूथपिक सूखी और साफ़ न निकले। मेरे मफिन 24 मिनट में बिल्कुल सही बने थे।","बचे हुए मफिन को सीलबंद डिब्बे में या कसकर लपेटकर कमरे के तापमान पर 1-2 दिन रखें। उन्हें 5 दिन तक फ्रिज में रखें, या एयरटाइट डिब्बे में 3 महीने तक फ्रीज़ करें।"],
[]),
(9790342,"स्मोक्ड टोफू","बेहद धुएं जैसी खुशबू और स्वाद से भरपूर! यह स्मोक्ड टोफू ज़रूर आज़माएं, और इन शानदार नतीजों के लिए आपको स्मोकर की भी ज़रूरत नहीं है।","4 सर्विंग","1 सर्विंग",
["350 ग्राम (12 औंस) का 1 ब्लॉक एक्स्ट्रा सख्त टोफू, हो सके तो GMO-मुक्त ऑर्गेनिक टोफू चुनें","मैरिनेड के लिए::¼ कप कम सोडियम वाली सोया सॉस या ग्लूटेन-मुक्त के लिए तमारी","मैरिनेड के लिए::¼ कप पानी","मैरिनेड के लिए::3 बड़े चम्मच मेपल सिरप","मैरिनेड के लिए::1 बड़ा चम्मच लिक्विड स्मोक","मैरिनेड के लिए::1 बड़ा चम्मच स्मोक्ड पैपरिका","मैरिनेड के लिए::1 छोटा चम्मच लहसुन पाउडर","वैकल्पिक: स्मोक्ड टोफू को ग्रिल करने के लिए::बचा हुआ मैरिनेड","वैकल्पिक: स्मोक्ड टोफू को ग्रिल करने के लिए::⅓ कप पानी","वैकल्पिक: स्मोक्ड टोफू को ग्रिल करने के लिए::1 बड़ा चम्मच टैपिओका स्टार्च या कॉर्नस्टार्च"],
["अपने टोफू के ब्लॉक को लगभग 1/4 इंच मोटे आयतों में काटें।",
"फिर एक कटिंग बोर्ड पर साफ़ तौलिया (या पेपर टॉवल) रखें और स्लाइस को उसके ऊपर एक परत में सजाएं। स्लाइस के ऊपर एक और साफ़ तौलिया रखें, फिर उसके ऊपर एक और कटिंग बोर्ड (या सपाट बेकिंग पैन) रखें। फिर आखिर में उसके ऊपर कोई भारी चीज़ रखें, जैसे कच्चे लोहे का पैन या भारी किताबें। इसे 15 मिनट तक ऐसे ही रखें।",
"इसी बीच, मैरिनेड की सारी सामग्री एक छोटे बाउल में डालें और मिलाने के लिए चलाएं।",
"दबाए हुए टोफू को एक चौड़े लेकिन उथले बर्तन में एक परत में सजाएं और ऊपर से मैरिनेड डालें। 60 मिनट फ्रिज में रखें, और बीच में स्लाइस को सावधानी से पलट दें।",
"जब आपके टोफू के भीगने में लगभग 10 मिनट बचे हों, तो ओवन को 400°F/204°C पर पहले से गरम करें और बेकिंग शीट पर बटर पेपर बिछा दें। स्लाइस को एक परत में सजाएं और 15 मिनट बेक करें। फिर उन्हें पलटें और 15-18 मिनट और बेक करें। नोट: मैरिनेड का तरल बचाकर रखें!",
"वैकल्पिक: स्मोक्ड टोफू को ग्रिल करने के लिए::नॉनस्टिक ग्रिल गरम करें, या ज़रूरत हो तो अपनी ग्रिल पर हल्की चिकनाई लगाएं।",
"वैकल्पिक: स्मोक्ड टोफू को ग्रिल करने के लिए::बचे हुए मैरिनेड को एक छोटे सॉसपैन में डालें और 1/3 कप पानी और एक बड़ा चम्मच टैपिओका आटा डालें। अच्छी तरह फेंटें और गाढ़ा करके अपनी बारबेक्यू सॉस बनाने के लिए मध्यम आंच पर 2-3 मिनट धीमी आंच पर पकाएं।",
"वैकल्पिक: स्मोक्ड टोफू को ग्रिल करने के लिए::स्मोक्ड टोफू के स्लाइस के दोनों ओर अपनी सॉस लगाएं और उन्हें ग्रिल पर तिरछा रखें ताकि ग्रिल की धारियां बनें, हर तरफ लगभग 1-2 मिनट।"],
["पहले से योजना बनाएं! आप टोफू को एक दिन पहले मैरिनेट कर सकते हैं ताकि परोसने वाले दिन समय बचे।","हालांकि कुल समय 2 घंटे से थोड़ा ज़्यादा लगता है, ध्यान रहे कि यह सारा समय काम करने का नहीं है और टोफू फ्रिज में 1 घंटे मैरिनेट होता है।","बचा हुआ टोफू सीलबंद डिब्बे में फ्रिज में 3-4 दिन तक रखा जा सकता है।"],
[]),
(9791180,"मिसो पेस्तो पास्ता","ताज़ा और बेहद स्वादिष्ट मिसो पेस्तो पास्ता!","4 सर्विंग","1 सर्विंग",
["1.5 कप ताज़ा तुलसी के पत्ते, हल्के से दबाकर भरे हुए","½ कप बिना नमक के सूरजमुखी के बीज","3-4 लहसुन की कलियां","3 बड़े चम्मच सफेद मिसो पेस्ट","3 बड़े चम्मच एप्पल साइडर सिरका","2-4 बड़े चम्मच छना हुआ पानी, ज़रूरत हो तो","½ पाउंड फेटुचीनी या अपनी पसंद का पास्ता"],
["एक बड़े पतीले में नमक वाला पानी उबालें और अपने पास्ता को पैकेट पर लिखे निर्देशों के अनुसार 'अल डेंते' पास्ता के लिए पकाएं। अगर 'अल डेंते' के लिए पैकेट पर कोई निर्देश नहीं हैं, तो पास्ता को 1-2 मिनट कम पकाएं।",
"पास्ता के पानी में से 1/2 कप बचाकर रखें, पास्ता छान लें, उसे वापस पतीले में डालें और एक तरफ रख दें।",
"इसी बीच, पेस्तो की सारी सामग्री अपने फूड प्रोसेसर में डालें, मिलने तक ब्लेंड करें और ज़रूरत हो तो 2-4 बड़े चम्मच पानी डालें।",
"पके हुए पास्ता को मिसो पेस्तो के साथ मिलाएं, और अपने स्वाद के अनुसार सॉस को पतला करने के लिए बचाए हुए पास्ता के पानी में से जितना चाहें उतना डालें। फिर परोसें।"],
["बिना नमक वाले सूरजमुखी के बीज इस्तेमाल करें ताकि व्यंजन ज़्यादा नमकीन न हो जाए।","अपने पकाने के पानी में नमक डालें। सबसे अच्छी बनावट और स्वाद के लिए अपने पानी के पतीले में पर्याप्त नमक डालना न भूलें। हर बार पानी में बिल्कुल सही नमक डालने में मदद के लिए यहां एक काम की गाइड है।","'अल डेंते' बनावट तक पकाएं। ज़्यादा न पकाएं! अल डेंते का मतलब है कि पकने के बाद भी पास्ता कुछ सख्त रहता है, जिससे हर कौर में सबसे बढ़िया बनावट मिलती है। यह ज़्यादा न पके, इसके लिए पैकेट पर बताए गए समय से कुछ मिनट पहले चखना शुरू कर दें। यह नरम होना चाहिए, लेकिन फिर भी थोड़ा सख्त।","पास्ता छानने से पहले थोड़ा मांड वाला पकाने का पानी बचाकर रखें, ताकि मिसो पेस्तो सॉस को अपने स्वाद के अनुसार पतला कर सकें।"],
[]),
]
P(2,R)
